CREATE TABLE IF NOT EXISTS settings (id integer PRIMARY KEY CHECK (id=1), password_hash text NOT NULL, session_version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS sessions (id uuid PRIMARY KEY, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS accounts (id serial PRIMARY KEY, name varchar(80) NOT NULL UNIQUE, type text NOT NULL CHECK(type IN ('bank','cash','savings','emergency','credit')), opening_balance numeric(14,2) NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS categories (id serial PRIMARY KEY, name varchar(60) NOT NULL UNIQUE, color varchar(7) NOT NULL, icon varchar(20) NOT NULL DEFAULT '•', bucket text NOT NULL DEFAULT 'needs' CHECK(bucket IN ('needs','wants','savings')));
CREATE TABLE IF NOT EXISTS recurring_rules (id serial PRIMARY KEY, type text NOT NULL CHECK(type IN ('income','expense')), amount numeric(14,2) NOT NULL CHECK(amount>0), category_id integer REFERENCES categories(id), account_id integer NOT NULL REFERENCES accounts(id), note varchar(500) NOT NULL DEFAULT '', period text NOT NULL CHECK(period IN ('weekly','monthly','yearly')), next_date date NOT NULL, anchor_day integer NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS transactions (id serial PRIMARY KEY, type text NOT NULL CHECK(type IN ('income','expense')), amount numeric(14,2) NOT NULL CHECK(amount>0), category_id integer REFERENCES categories(id), subcategory varchar(80) NOT NULL DEFAULT '', account_id integer NOT NULL REFERENCES accounts(id), method text NOT NULL CHECK(method IN ('cash','card','bank','transfer')), note varchar(500) NOT NULL DEFAULT '', date date NOT NULL, recurring_id integer REFERENCES recurring_rules(id) ON DELETE SET NULL, UNIQUE(recurring_id,date));
CREATE INDEX IF NOT EXISTS transactions_date_idx ON transactions(date);
CREATE INDEX IF NOT EXISTS transactions_category_idx ON transactions(category_id,date);
CREATE TABLE IF NOT EXISTS transfers (id serial PRIMARY KEY, from_id integer NOT NULL REFERENCES accounts(id), to_id integer NOT NULL REFERENCES accounts(id), amount numeric(14,2) NOT NULL CHECK(amount>0), date date NOT NULL, CHECK(from_id<>to_id));
CREATE TABLE IF NOT EXISTS budgets (id serial PRIMARY KEY, month varchar(7) NOT NULL, category_id integer REFERENCES categories(id), amount numeric(14,2) NOT NULL CHECK(amount>0));
CREATE UNIQUE INDEX IF NOT EXISTS budget_unique_idx ON budgets(month,COALESCE(category_id,0));
CREATE TABLE IF NOT EXISTS trades (id serial PRIMARY KEY, symbol varchar(20) NOT NULL, side text NOT NULL CHECK(side IN ('buy','sell')), quantity numeric(22,8) NOT NULL CHECK(quantity>0), price numeric(14,2) NOT NULL CHECK(price>0), fee numeric(14,2) NOT NULL DEFAULT 0 CHECK(fee>=0), date date NOT NULL, account_id integer NOT NULL REFERENCES accounts(id));
CREATE INDEX IF NOT EXISTS trades_symbol_date_idx ON trades(symbol,date,id);
CREATE TABLE IF NOT EXISTS quote_cache (symbol varchar(20) PRIMARY KEY, data jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS watchlist (symbol varchar(20) PRIMARY KEY, target numeric(14,2), direction text NOT NULL DEFAULT 'below' CHECK(direction IN ('below','above')));
CREATE TABLE IF NOT EXISTS goals (id serial PRIMARY KEY, name varchar(80) NOT NULL, target numeric(14,2) NOT NULL CHECK(target>0), deadline date NOT NULL, created_at date NOT NULL DEFAULT CURRENT_DATE);
CREATE TABLE IF NOT EXISTS goal_contributions (id serial PRIMARY KEY, goal_id integer NOT NULL REFERENCES goals(id) ON DELETE CASCADE, account_id integer NOT NULL REFERENCES accounts(id), amount numeric(14,2) NOT NULL CHECK(amount<>0), date date NOT NULL);
CREATE TABLE IF NOT EXISTS snapshots (date date PRIMARY KEY, net_worth numeric(14,2) NOT NULL, portfolio numeric(14,2) NOT NULL, cost_basis numeric(14,2) NOT NULL, profit numeric(14,2) NOT NULL);
CREATE TABLE IF NOT EXISTS news_cache (key text PRIMARY KEY, data jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS api_calls (id bigserial PRIMARY KEY, at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS api_calls_at_idx ON api_calls(at);
